const $=id=>document.getElementById(id),normal=p=>p.replace(/\\/g,'/').replace(/^\.:/,'').replace(/:/g,'/').replace(/^\.\//,'');
export function setupBookManager({importGuide,toast,pauseScene}){
 const dialog=document.createElement('dialog');dialog.id='bookManager';dialog.innerHTML=`<header class="book-head"><div><small>EPISODE LIBRARY</small><h2>작품 · 페이지 관리</h2></div><button id="bookClose">편집기로 돌아가기 ✕</button></header><nav class="book-actions"><button id="bookFolder" class="primary">폴더 연결</button><button id="bookFiles">CMC · CLIP 선택</button><button id="bookZip">ZIP 열기</button><button id="bookReconnect">최근 폴더</button><select id="bookChoice" aria-label="관리 파일 선택"></select><button id="bookRefresh">변경 확인 ↻</button><label class="check"><input id="bookAuto" type="checkbox" checked> 자동 확인</label><label class="check"><input id="bookFit" type="checkbox" checked> 전체 높이 맞춤</label><label>보기 폭 <input id="bookScale" type="range" min="60" max="200" value="100"></label></nav><div id="bookMessage" role="status">CMC와 CLIP이 함께 있는 폴더 또는 ZIP을 선택하세요. 파일은 이 브라우저에서만 읽습니다.</div><div class="book-body"><div id="bookOverview"><div class="book-empty">한 화를 한눈에.<br><small>긴 페이지를 나란히 확인하고, 필요한 부분을 콘티로 가져오세요.</small></div></div><aside id="bookDetail"><h3 id="bookPageTitle">페이지를 선택하세요</h3><p id="bookDimensions"></p><div id="bookDetailScroll"><div id="bookPreviewWrap"><img id="bookPreview" alt="선택한 CLIP의 저장 미리보기"><div id="bookCropBand"></div></div></div><div class="book-crop"><b>콘티 가이드로 가져올 구간</b><div class="two"><label>시작 Y · 원본 px<input id="bookCropStart" type="number" min="0" value="0"></label><label>끝 Y · 원본 px<input id="bookCropEnd" type="number" min="1" value="1600"></label></div><button id="bookImport" class="primary full" disabled>선택 구간을 새 컷으로</button><small>미리보기 위를 세로로 드래그해서 구간을 선택할 수 있습니다. 가져온 이미지는 참고용이며 원본 레이어는 유지되지 않습니다.</small></div><details id="bookLayers"><summary>원본 레이어 구조 <span id="bookLayerCount"></span></summary><div id="bookLayerTree"></div></details></aside></div><footer id="bookFoot">원본 CMC·CLIP은 수정하지 않습니다. 웹 콘티는 별도의 프로젝트와 PSD로 저장됩니다.</footer><input id="bookFolderInput" type="file" webkitdirectory multiple hidden><input id="bookFilesInput" type="file" accept=".cmc,.clip" multiple hidden><input id="bookZipInput" type="file" accept=".zip" hidden>`;
 document.body.append(dialog);const button=document.createElement('button');button.id='bookOpen';button.className='full';button.textContent='▥ 작품 · CMC 페이지';$('libraryBtn').before(button);
 const welcome=document.createElement('button');welcome.className='textlink';welcome.textContent='CMC · 작품 폴더 열기 →';$('openProject').after(welcome);
 let worker=new Worker(new URL('./book-worker.js?v=20261025-release1',import.meta.url)),serial=0,pending=new Map(),files=new Map(),handle=null,pages=[],cache=new Map(),selected=null,detailURL=null,epoch=0,busy=false,sourceLabel='',zipMode=false;
 worker.onmessage=e=>{const task=pending.get(e.data.id);if(!task)return;pending.delete(e.data.id);e.data.error?task.reject(Error(e.data.error)):task.resolve(e.data.result);};
 worker.onerror=()=>{for(const task of pending.values())task.reject(Error('파일 읽기 작업을 완료하지 못했습니다.'));pending.clear();};
 const call=(kind,file)=>new Promise((resolve,reject)=>{const id=++serial;pending.set(id,{resolve,reject});worker.postMessage({id,kind,file});});
 const message=s=>$('bookMessage').textContent=s;
 async function connection(value){return new Promise((resolve,reject)=>{const request=indexedDB.open('scroll-book-link',1);request.onupgradeneeded=()=>request.result.createObjectStore('links');request.onerror=()=>reject(request.error);request.onsuccess=()=>{const db=request.result,tx=db.transaction('links',value?'readwrite':'readonly'),q=value?tx.objectStore('links').put(value,'recent'):tx.objectStore('links').get('recent');q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error);tx.oncomplete=()=>db.close();};});}
 async function enumerate(directory,prefix='',depth=0){if(depth>8)throw Error('폴더 계층이 너무 깊습니다. 작품 폴더를 직접 선택하세요.');const result=[];for await(const [name,entry]of directory.entries()){if(entry.kind==='directory')result.push(...await enumerate(entry,prefix+name+'/',depth+1));else if(/\.(cmc|clip)$/i.test(name))result.push({path:prefix+name,file:await entry.getFile()});if(result.length>350)throw Error('작품 하나의 폴더를 선택하세요.');}return result;}
 function controls(){for(const id of ['bookFolder','bookFiles','bookZip','bookReconnect','bookChoice','bookRefresh'])$(id).disabled=busy;$('bookImport').disabled=busy||!detailURL;$('bookAuto').disabled=!handle;$('bookRefresh').textContent=handle?'변경 확인 ↻':'파일 다시 선택 ↻';}
 async function run(fn){if(busy)return;busy=true;controls();try{await fn();}catch(e){message(e.message);toast(e.message);}finally{busy=false;controls();}}
 async function attach(entries,label,{directory=null,isZip=false}={}){
  if(!entries.length)throw Error('CMC 또는 CLIP 파일이 없습니다.');handle=directory;zipMode=isZip;sourceLabel=label;$('bookAuto').checked=!!directory;files=new Map(entries.map(e=>[normal(e.path),e.file]));
  for(const item of cache.values())URL.revokeObjectURL(item.url);cache.clear();selected=null;clearDetail();
  const cmcs=[...files.keys()].filter(p=>/\.cmc$/i.test(p));$('bookChoice').replaceChildren();for(const path of cmcs)$('bookChoice').add(new Option(path,path));if(!cmcs.length)$('bookChoice').add(new Option('CLIP 파일 이름순',''));await indexPages();
 }
 async function indexPages(){
  const token=++epoch,path=$('bookChoice').value;let list;
  if(path){const book=await call('book',files.get(path)),base=path.includes('/')?path.slice(0,path.lastIndexOf('/')+1):'';list=book.pages.map(p=>{const key=normal(base+normal(p.path));return {path:key};});}
  else list=[...files.keys()].filter(p=>/\.clip$/i.test(p)).sort((a,b)=>a.localeCompare(b,undefined,{numeric:true})).map(path=>({path}));
  if(!list.length)throw Error('표시할 페이지 연결이 없습니다.');if(list.length>300)throw Error('300페이지 이하의 작품을 선택하세요.');
  const orderChanged=pages.map(p=>p.path).join('|')!==list.map(p=>p.path).join('|');pages=list;if(orderChanged||!$('bookOverview').querySelector('.book-page'))renderOverview();let failures=0,updated=0,selectedChanged=false;
  for(let i=0;i<pages.length;i++){
   if(token!==epoch)return;const page=pages[i],file=files.get(page.path),card=$('bookOverview').children[i];
   if(!file){page.error='연결 파일 없음';card.querySelector('img').removeAttribute('src');card.querySelector('small').textContent=page.error;failures++;continue;}
   const signature=file.size+':'+file.lastModified;let item=cache.get(page.path);
   if(!item||item.signature!==signature){message(`${sourceLabel} · ${i+1}/${pages.length} 페이지 정보 읽는 중…`);try{const data=await call('page',file);if(token!==epoch)return;if(item)URL.revokeObjectURL(item.url);item={...data,signature,url:URL.createObjectURL(data.thumb)};cache.set(page.path,item);updated++;if(page.path===selected)selectedChanged=true;}catch(e){page.error=e.message;failures++;card.querySelector('small').textContent=e.message;continue;}}
   if(card.querySelector('img').getAttribute('src')!==item.url)card.querySelector('img').src=item.url;card.querySelector('img').style.aspectRatio=item.width+'/'+item.height;card.querySelector('small').textContent=`${item.width} × ${item.height}`;card.dataset.ready='true';fitOverview();
  }
  const valid=new Set(pages.map(p=>p.path));for(const [key,item]of cache)if(!valid.has(key)){URL.revokeObjectURL(item.url);cache.delete(key);}
  message(`${sourceLabel} · ${pages.length}페이지 · ${updated?updated+'페이지 갱신':'변경 없음'}${failures?' · '+failures+'페이지 확인 필요':''} · ${handle?'연결 중: 10초마다 변경 확인':'다시 선택하면 저장된 변경 내용을 읽습니다.'}`);
  if(selected&&valid.has(selected)){if(selectedChanged)await showPage(selected);}else if(selected){selected=null;clearDetail();}
 }
 function renderOverview(){const overview=$('bookOverview');overview.replaceChildren();pages.forEach((p,i)=>{const card=document.createElement('button');card.className='book-page';card.classList.toggle('active',p.path===selected);const title=document.createElement('b');title.textContent=String(i+1).padStart(2,'0');card.title=p.path;const image=document.createElement('img');image.alt='페이지 '+(i+1)+' 미리보기';image.loading='lazy';const small=document.createElement('small');small.textContent='읽는 중…';card.append(title,image,small);card.onclick=()=>showPage(p.path).catch(e=>message(e.message));overview.append(card);});}
 function clearDetail(){++detailEpoch;if(detailURL)URL.revokeObjectURL(detailURL);detailURL=null;$('bookPreview').removeAttribute('src');$('bookImport').disabled=true;$('bookLayerTree').replaceChildren();$('bookDetail').hidden=true;$('bookPageTitle').textContent='페이지를 선택하세요';$('bookDimensions').textContent='';$('bookCropBand').hidden=true;}
 let detailEpoch=0;
 async function showPage(path){
  const item=cache.get(path),file=files.get(path);if(!item||!file)return message('이 페이지는 읽을 수 없습니다. CMC와 연결된 CLIP 파일을 함께 선택하세요.');selected=path;$('bookDetail').hidden=false;const token=++detailEpoch;$('bookImport').disabled=true;
  [...$('bookOverview').children].forEach((el,i)=>el.classList.toggle('active',pages[i].path===path));$('bookPageTitle').textContent=path.split('/').pop();$('bookDimensions').textContent=`${item.width} × ${item.height}px · ${item.dpi}dpi · 저장 미리보기 ${item.previewWidth}px 폭`;
  const result=await call('preview',file);if(token!==detailEpoch)return;if(detailURL)URL.revokeObjectURL(detailURL);detailURL=URL.createObjectURL(result.blob);$('bookPreview').src=detailURL;await $('bookPreview').decode();if(token!==detailEpoch)return;
  $('bookCropStart').value=0;$('bookCropEnd').value=Math.min(item.height,item.width*1.2);$('bookCropStart').max=item.height-1;$('bookCropEnd').max=item.height;$('bookImport').disabled=false;updateBand();$('bookDetailScroll').scrollTop=0;renderLayers(item);
 }
 function renderLayers(item){const root=$('bookLayerTree');root.replaceChildren();const map=new Map(item.layers.map(l=>[l.MainId,l])),seen=new Set();function walk(id,depth){while(id&&!seen.has(id)){seen.add(id);const l=map.get(id);if(!l)return;const row=document.createElement('div');row.style.paddingLeft=Math.min(depth,8)*10+'px';row.textContent=`${l.LayerFolder?'▸':'·'} ${l.LayerName||'원고'}  ${Math.round(l.LayerOpacity/256*100)}%`;root.append(row);if(l.LayerFirstChildIndex)walk(l.LayerFirstChildIndex,depth+1);id=l.LayerNextIndex;}}walk(item.root,0);$('bookLayerCount').textContent=`(${item.layers.length})`;}
 function range(){const item=cache.get(selected);if(!item)return null;const start=Math.max(0,Math.min(item.height-1,Number($('bookCropStart').value)||0)),end=Math.max(start+1,Math.min(item.height,Number($('bookCropEnd').value)||start+1));return {item,start,end};}
 function updateBand(){const r=range();if(!r)return;const band=$('bookCropBand');band.hidden=false;band.style.top=r.start/r.item.height*100+'%';band.style.height=(r.end-r.start)/r.item.height*100+'%';band.textContent=Math.round(r.end-r.start)+'px';}
 for(const id of ['bookCropStart','bookCropEnd'])$(id).oninput=updateBand;
 let drag=null;const wrap=$('bookPreviewWrap');wrap.onpointerdown=e=>{if(!selected||!detailURL)return;const rect=wrap.getBoundingClientRect(),item=cache.get(selected);drag={start:Math.max(0,Math.min(item.height,(e.clientY-rect.top)/rect.height*item.height)),item};wrap.setPointerCapture(e.pointerId);e.preventDefault();};wrap.onpointermove=e=>{if(!drag)return;const rect=wrap.getBoundingClientRect(),y=Math.max(0,Math.min(drag.item.height,(e.clientY-rect.top)/rect.height*drag.item.height));$('bookCropStart').value=Math.round(Math.min(drag.start,y));$('bookCropEnd').value=Math.round(Math.max(drag.start+1,y));updateBand();};wrap.onpointerup=wrap.onpointercancel=()=>drag=null;
 $('bookImport').onclick=()=>run(async()=>{const r=range();if(!r||!detailURL)return;await importGuide({image:$('bookPreview'),...r,name:selected.split('/').pop()});dialog.close();});
 async function refresh(){if(!handle){(zipMode?$('bookZipInput'):$('bookFolderInput')).click();return;}await run(async()=>{const entries=await enumerate(handle);files=new Map(entries.map(e=>[normal(e.path),e.file]));if(!files.has($('bookChoice').value)&&$('bookChoice').value)throw Error('관리 파일이 이동되었습니다. 폴더를 다시 연결하세요.');await indexPages();});}
 $('bookFolder').onclick=async()=>{if(!window.showDirectoryPicker)return $('bookFolderInput').click();try{const dir=await showDirectoryPicker({mode:'read'});await run(async()=>{await attach(await enumerate(dir),dir.name,{directory:dir});await connection(dir).catch(()=>{});});}catch(e){if(e.name!=='AbortError'){$('bookFolderInput').click();message('이 브라우저에서는 폴더를 선택해 다시 읽는 방식으로 연결합니다.');}}};
 $('bookReconnect').onclick=()=>run(async()=>{const dir=await connection();if(!dir)throw Error('저장된 폴더 연결이 없습니다. 폴더 연결을 눌러주세요.');if(await dir.requestPermission({mode:'read'})!=='granted')throw Error('폴더 읽기 권한이 필요합니다.');await attach(await enumerate(dir),dir.name,{directory:dir});});
 $('bookFiles').onclick=()=>$('bookFilesInput').click();$('bookZip').onclick=()=>$('bookZipInput').click();
 for(const id of ['bookFolderInput','bookFilesInput'])$(id).onchange=e=>{const entries=[...e.target.files].filter(f=>/\.(cmc|clip)$/i.test(f.name)).map(file=>({path:file.webkitRelativePath||file.name,file}));if(entries.length)run(()=>attach(entries,entries[0].path.includes('/')?entries[0].path.split('/')[0]:'선택한 작품'));e.target.value='';};
 $('bookZipInput').onchange=e=>{const file=e.target.files[0];if(file)run(async()=>{message('ZIP에서 작품 파일을 읽는 중…');const result=await call('zip',file);await attach(result.files,file.name,{isZip:true});});e.target.value='';};
 $('bookChoice').onchange=()=>run(async()=>{selected=null;clearDetail();await indexPages();});$('bookRefresh').onclick=refresh;
 function fitOverview(){if(!$('bookFit').checked)return;const ratios=pages.map(p=>cache.get(p.path)).filter(Boolean).map(p=>p.height/p.width);const width=Math.max(18,Math.min(200,($('bookOverview').clientHeight-80)/Math.max(1,...ratios)));$('bookOverview').style.setProperty('--page-width',width+'px');}
 $('bookFit').onchange=()=>{if($('bookFit').checked)fitOverview();else $('bookOverview').style.setProperty('--page-width',$('bookScale').value+'px');};new ResizeObserver(fitOverview).observe($('bookOverview'));
 $('bookScale').oninput=e=>{$('bookFit').checked=false;$('bookOverview').style.setProperty('--page-width',e.target.value+'px');};
 const open=()=>{pauseScene();dialog.showModal();fitOverview();};button.onclick=welcome.onclick=open;$('bookClose').onclick=()=>dialog.close();
 setInterval(()=>{if(dialog.open&&!document.hidden&&handle&&$('bookAuto').checked&&!busy)refresh();},10000);
 clearDetail();
 window.addEventListener('focus',()=>{if(dialog.open&&handle&&$('bookAuto').checked&&!busy)refresh();});controls();
 return {open};
}
